import { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { assistantSources, companies, mockQuestions, questions, readinessSkills, roadmapPhases, todayPlan } from './data'
import './styles.css'

const iconPaths = {
  dashboard: <><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,
  companies: <><path d="M4 21V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v16"/><path d="M2 21h20M8 7h4M8 11h4M8 15h4M18 10h2v11"/></>,
  practice: <><path d="m8 9-3 3 3 3M16 9l3 3-3 3M14 5l-4 14"/></>,
  test: <><rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V3h6v1M9 10h6M9 14h5"/></>,
  roadmap: <><circle cx="6" cy="18" r="2"/><circle cx="18" cy="6" r="2"/><path d="M8 17c5-1 2-8 8-9"/></>,
  progress: <><path d="M4 19V5M4 19h17"/><path d="m7 15 4-4 3 2 5-6"/></>,
  readiness: <><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v2M22 12h-2M12 22v-2M2 12h2"/></>,
  resume: <><path d="M8 3h6l4 4v14H6V3Z"/><path d="M14 3v5h5M9 13h6M9 17h4"/></>,
  assistant: <><path d="M12 3 9.5 9.5 3 12l6.5 2.5L12 21l2.5-6.5L21 12l-6.5-2.5L12 3Z"/><path d="m19 16-.6 2.4L16 19l2.4.6L19 22l.6-2.4L22 19l-2.4-.6L19 16Z"/></>,
  interview: <><path d="M12 18a6 6 0 0 0 6-6V8a6 6 0 0 0-12 0v4a6 6 0 0 0 6 6Z"/><path d="M19 11v1a7 7 0 0 1-14 0v-1M12 19v3M8 22h8"/></>,
  analytics: <><path d="M4 19V5M4 19h17"/><path d="M7 15v-3M11 15V8M15 15v-6M19 15V6"/></>,
  admin: <><circle cx="12" cy="8" r="3"/><path d="M5 21v-1a7 7 0 0 1 14 0v1M19 4v5M21.5 6.5h-5"/></>,
  bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></>,
  chevron: <path d="m9 18 6-6-6-6"/>, arrow: <><path d="M5 12h14M13 6l6 6-6 6"/></>,
  check: <path d="m5 12 4.2 4.2L19 6.5"/>, plus: <path d="M12 5v14M5 12h14"/>, close: <><path d="m6 6 12 12M18 6 6 18"/></>,
  bookmark: <path d="M6 4a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v18l-6-4-6 4V4Z"/>, timer: <><circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6"/></>,
  filter: <><path d="M4 6h16M7 12h10M10 18h4"/></>, upload: <><path d="M12 16V3M7 8l5-5 5 5"/><path d="M5 14v5h14v-5"/></>,
  file: <><path d="M8 3h6l4 4v14H6V3Z"/><path d="M14 3v5h5"/></>, send: <><path d="m21 3-8 18-3.5-7.5L3 10 21 3Z"/><path d="m9.5 13.5 4-4"/></>, target: <><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/></>,
}
function Icon({ name, size = 18 }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{iconPaths[name]}</svg> }
const cx = (...classes) => classes.filter(Boolean).join(' ')
const pct = value => `${Math.max(0, Math.min(value, 100))}%`
const navItems = [['Dashboard','dashboard'],['Requirements','readiness'],['Companies','companies'],['Practice','practice'],['Mock Tests','test'],['Roadmap','roadmap'],['Progress','progress'],['Readiness','readiness'],['Resume Analyzer','resume'],['HireVerse Assistant','assistant'],['AI Interview','interview'],['Analytics','analytics']]

function App() {
  const [page, setPage] = useState('Dashboard'), [companyId, setCompanyId] = useState('accenture'), [role, setRole] = useState('Full Stack Developer'), [toast, setToast] = useState(null), [targetOpen, setTargetOpen] = useState(false), [notificationsOpen, setNotificationsOpen] = useState(false), [profileOpen, setProfileOpen] = useState(false), [journeyStarted, setJourneyStarted] = useState(false)
  const [profile, setProfile] = useState({ name: 'Arjun Sharma', branch: 'Computer Engineering', year: 'Final year' }), [completedPlan, setCompletedPlan] = useState(['arrays']), [roadmapDone, setRoadmapDone] = useState(['array-basics','linked-list']), [bookmarks, setBookmarks] = useState([]), [reviewed, setReviewed] = useState([]), [adminQuestions, setAdminQuestions] = useState(questions), [skillStatus, setSkillStatus] = useState({ JavaScript: 'In Progress', React: 'Completed', 'Node.js': 'In Progress', SQL: 'Completed', DBMS: 'In Progress', DSA: 'Not Started', 'Git & GitHub': 'Completed', Aptitude: 'In Progress', Communication: 'Not Started' })
  const currentCompany = companies.find(company => company.id === companyId) || companies[0]
  const showToast = (message, tone = 'success') => { setToast({ message, tone }); window.setTimeout(() => setToast(null), 2600) }
  const setTarget = (id, nextRole) => { const next = companies.find(company => company.id === id) || companies[0]; setCompanyId(next.id); setRole(nextRole || next.roles[0]); showToast(`${next.name} ${nextRole || next.roles[0]} is now your target`) }
  const appProps = { currentCompany, role, setPage, showToast, completedPlan, setCompletedPlan, roadmapDone, setRoadmapDone, bookmarks, setBookmarks, reviewed, setReviewed, adminQuestions, setAdminQuestions, skillStatus, setSkillStatus }
  const views = { Dashboard, Requirements, Companies, 'Company guide': CompanyGuide, Practice, 'Mock Tests': PracticeTests, Roadmap, Progress: SimpleProgress, Readiness, 'Resume Analyzer': SimpleResume, 'HireVerse Assistant': Assistant, 'AI Interview': JourneyInterview, Analytics, Admin }
  const View = views[page] || Dashboard
  if (!journeyStarted) return <GoalSetup defaultCompany={companyId} defaultRole={role} setTarget={setTarget} start={() => { setJourneyStarted(true); setPage('Requirements') }}/>
  return <div className="app"><Sidebar page={page} setPage={setPage}/><div className="app-main"><Topbar currentCompany={currentCompany} role={role} profile={profile} onTarget={() => setTargetOpen(true)} notificationsOpen={notificationsOpen} setNotificationsOpen={setNotificationsOpen} profileOpen={profileOpen} setProfileOpen={setProfileOpen}/><main className="content"><View {...appProps} setTarget={setTarget}/></main></div>{targetOpen && <TargetModal companyId={companyId} role={role} setTarget={setTarget} close={() => setTargetOpen(false)}/>} {profileOpen && <ProfileModal profile={profile} setProfile={setProfile} close={() => setProfileOpen(false)} showToast={showToast}/>} {toast && <Toast {...toast}/>}</div>
}

function Sidebar({ page, setPage }) { const active = page === 'Company guide' ? 'Companies' : page; return <aside className="sidebar"><a className="brand" href="#top" onClick={() => setPage('Dashboard')}><span className="brand-mark">H</span><span>Hire<span>Verse</span></span></a><p className="nav-label">PREPARATION</p><nav>{navItems.map(([label, icon]) => <button key={label} className={cx('nav-link', active === label && 'active')} onClick={() => setPage(label)}><Icon name={icon}/><span>{label}</span></button>)}</nav><div className="sidebar-footer"><p className="nav-label">MANAGEMENT</p><button className={cx('nav-link', page === 'Admin' && 'active')} onClick={() => setPage('Admin')}><Icon name="admin"/><span>Admin</span></button><div className="sidebar-help"><Icon name="assistant" size={17}/><div><strong>Need help?</strong><span>Learn how HireVerse works</span></div></div></div></aside> }
function Topbar({ currentCompany, role, profile, onTarget, notificationsOpen, setNotificationsOpen, profileOpen, setProfileOpen }) { return <header className="topbar"><div className="target-switch"><span>Preparing for</span><button onClick={onTarget}><CompanyMark company={currentCompany}/><strong>{currentCompany.name}</strong><em>·</em>{role}<Icon name="chevron" size={15}/></button></div><div className="topbar-actions"><button className="notification-button" aria-label="Notifications" onClick={() => setNotificationsOpen(!notificationsOpen)}><Icon name="bell"/><b/></button>{notificationsOpen && <Notifications close={() => setNotificationsOpen(false)}/>}<button className="profile-button" onClick={() => setProfileOpen(!profileOpen)}><span>{profile.name.split(' ').map(word => word[0]).join('').slice(0, 2)}</span><div><strong>{profile.name}</strong><small>{profile.year}</small></div><Icon name="chevron" size={15}/></button></div></header> }
function Notifications({ close }) { const [read, setRead] = useState(false); return <div className="notification-popover"><div><strong>Notifications</strong><button onClick={() => setRead(true)}>{read ? 'All caught up' : 'Mark all read'}</button></div>{read ? <p className="empty-copy">You’re all caught up.</p> : <><article><i className="notice-dot"/><span><b>Roadmap reminder</b>Complete your DBMS activity to stay on track today.<small>10 minutes ago</small></span></article><article><i className="notice-dot blue"/><span><b>Mock test result is ready</b>Your Google preparation test improved by 6%.<small>Yesterday</small></span></article></>}<button className="popover-link" onClick={close}>Close</button></div> }
function TargetModal({ companyId, role, setTarget, close }) { const [nextCompany, setNextCompany] = useState(companyId); const company = companies.find(item => item.id === nextCompany) || companies[0]; const [nextRole, setNextRole] = useState(role); useEffect(() => setNextRole(company.roles[0]), [nextCompany]); return <Modal title="Change preparation target" close={close}><p className="modal-copy">Your roadmap, readiness score and recommendations will adapt to this target.</p><label className="field-label">Target company<select value={nextCompany} onChange={event => setNextCompany(event.target.value)}>{companies.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field-label">Target role<select value={nextRole} onChange={event => setNextRole(event.target.value)}>{company.roles.map(item => <option key={item}>{item}</option>)}</select></label><div className="modal-actions"><Button kind="secondary" onClick={close}>Cancel</Button><Button onClick={() => { setTarget(nextCompany, nextRole); close() }}>Save target</Button></div></Modal> }
function ProfileModal({ profile, setProfile, close, showToast }) { const [draft, setDraft] = useState(profile); return <Modal title="Your profile" close={close}><label className="field-label">Name<input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })}/></label><label className="field-label">Program<input value={draft.branch} onChange={event => setDraft({ ...draft, branch: event.target.value })}/></label><label className="field-label">Academic year<select value={draft.year} onChange={event => setDraft({ ...draft, year: event.target.value })}><option>Final year</option><option>Third year</option><option>Second year</option></select></label><div className="modal-actions"><Button kind="secondary" onClick={close}>Cancel</Button><Button onClick={() => { setProfile(draft); close(); showToast('Profile saved successfully') }}>Save changes</Button></div></Modal> }
function Modal({ title, children, close }) { return <div className="modal-backdrop" onMouseDown={close}><section className="modal" onMouseDown={event => event.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button onClick={close}><Icon name="close"/></button></div>{children}</section></div> }
function Toast({ message, tone }) { return <div className={cx('toast', tone)}><Icon name={tone === 'success' ? 'check' : 'bell'} size={17}/>{message}</div> }
function Button({ children, kind = 'primary', icon, onClick, disabled = false, type = 'button' }) { return <button type={type} disabled={disabled} className={cx('button', kind)} onClick={onClick}>{icon && <Icon name={icon} size={16}/>} {children}</button> }
function CompanyMark({ company, large = false }) { return <span className={cx('company-mark', large && 'large')} style={{ background: company.color }}>{company.mark}</span> }
function ProgressBar({ value, tone = 'blue', label, showValue = true }) { return <div className="progress-row">{label && <div><span>{label}</span>{showValue && <b>{value}%</b>}</div>}<i className={cx('progress-track', tone)}><em style={{ width: pct(value) }}/></i></div> }
function PageHeader({ eyebrow, title, description, children }) { return <section className="page-header"><div><p>{eyebrow}</p><h1>{title}</h1>{description && <span>{description}</span>}</div>{children && <div className="page-header-actions">{children}</div>}</section> }

function GoalSetup({ defaultCompany, defaultRole, setTarget, start }) {
  const [companyId, setCompanyId] = useState(defaultCompany)
  const company = companies.find(item => item.id === companyId) || companies[0]
  const [role, setRole] = useState(defaultRole)
  useEffect(() => { if (!company.roles.includes(role)) setRole(company.roles[0]) }, [companyId])
  return <main className="goal-setup"><section className="goal-brand"><span className="brand-mark">H</span><b>Hire<span>Verse</span></b></section><article className="goal-card"><p>PLACEMENT PREPARATION JOURNEY</p><h1>What job are you preparing for?</h1><span>Choose a target company and role. HireVerse will build a simple preparation plan around your goal.</span><div className="goal-fields"><label>Company<select value={companyId} onChange={event => setCompanyId(event.target.value)}>{companies.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Role<select value={role} onChange={event => setRole(event.target.value)}>{company.roles.map(item => <option key={item}>{item}</option>)}</select></label></div><div className="goal-preview"><CompanyMark company={company} large/><div><small>Your selected goal</small><strong>{role}</strong><span>at {company.name}</span></div></div><Button onClick={() => { setTarget(companyId, role); start() }}>Start preparation <Icon name="arrow" size={16}/></Button></article><p className="goal-note">Change your company or role anytime from the top bar.</p></main>
}

function Requirements({ currentCompany, role, skillStatus, setSkillStatus, setPage }) {
  const skills = currentCompany.id === 'accenture' ? ['JavaScript','React','Node.js','SQL','DBMS','DSA','Git & GitHub','Aptitude','Communication'] : currentCompany.skills.concat(['Aptitude','Communication']).slice(0, 9)
  const started = skills.filter(skill => skillStatus[skill] && skillStatus[skill] !== 'Not Started').length
  return <><PageHeader eyebrow="YOUR GOAL REQUIREMENTS" title={`${role} at ${currentCompany.name}`} description="These are the core skills to work through for your selected placement target."><Button kind="secondary" onClick={() => setPage('Roadmap')} icon="roadmap">Open preparation roadmap</Button></PageHeader><section className="requirements-hero"><div><CompanyMark company={currentCompany} large/><div><span>What you need to know</span><h2>{role} skills</h2><p>{started} of {skills.length} skill areas have been started.</p></div></div><aside><span>Your Skill Level</span><b>62%</b><ProgressBar value={62} tone="blue" showValue={false}/></aside></section><section className="requirements-list"><div className="requirements-head"><div><h2>Required skills</h2><span>Set a simple status for each skill as you progress.</span></div><span className="status-key"><i className="not-started"/>Not started <i className="in-progress"/>In progress <i className="completed"/>Completed</span></div>{skills.map((skill, index) => <div className="requirement-row" key={skill}><b>{String(index + 1).padStart(2, '0')}</b><strong>{skill}</strong><span>{skill === 'Communication' ? 'Explain your work clearly and confidently' : `Build practical confidence with ${skill}`}</span><select className={cx('skill-status', (skillStatus[skill] || 'Not Started').toLowerCase().replaceAll(' ', '-'))} value={skillStatus[skill] || 'Not Started'} onChange={event => setSkillStatus({ ...skillStatus, [skill]: event.target.value })}><option>Not Started</option><option>In Progress</option><option>Completed</option></select></div>)}</section><section className="requirements-next"><div><Icon name="roadmap" size={21}/><span><b>What should you do next?</b>Start with JavaScript foundations and keep your status current as you progress.</span></div><Button onClick={() => setPage('Roadmap')}>Start preparation <Icon name="arrow" size={15}/></Button></section></>
}

function Dashboard({ currentCompany, role, setPage, completedPlan, setCompletedPlan, roadmapDone }) { const overall = Math.round(readinessSkills.reduce((sum, skill) => sum + skill.score, 0) / readinessSkills.length); const togglePlan = id => setCompletedPlan(completedPlan.includes(id) ? completedPlan.filter(item => item !== id) : [...completedPlan, id]); const totalRoadmap = roadmapPhases.flatMap(phase => phase.items).length; return <><PageHeader eyebrow="PLACEMENT PREPARATION DASHBOARD" title="Your preparation, in one place." description="See what matters for your current company and role."><Button kind="secondary" onClick={() => setPage('Companies')} icon="companies">Explore companies</Button><Button onClick={() => setPage('Roadmap')} icon="roadmap">Continue roadmap</Button></PageHeader><section className="target-banner"><div className="target-company"><CompanyMark company={currentCompany} large/><div><span>Current target</span><h2>{currentCompany.name}</h2><p>{role}</p></div></div><div className="target-meta"><div><span>Recruitment focus</span><strong>{currentCompany.rounds[0]}</strong></div><div><span>Next milestone</span><strong>Mock test · 08 Oct</strong></div><Button kind="secondary" onClick={() => setPage('Company guide')}>View preparation guide <Icon name="arrow" size={15}/></Button></div></section><section className="dashboard-grid primary-grid"><article className="readiness-summary"><div className="section-head"><div><h2>Overall readiness</h2><span>Your company-specific preparation score</span></div><button onClick={() => setPage('Readiness')}>Detailed analysis <Icon name="arrow" size={15}/></button></div><div className="readiness-content"><div className="score-block"><strong>{overall}</strong><span>/ 100</span><p>On track</p></div><div className="readiness-bars">{readinessSkills.slice(0, 5).map(skill => <ProgressBar key={skill.name} label={skill.name} value={skill.score} tone={skill.status === 'strong' ? 'green' : skill.status === 'needs work' ? 'orange' : 'blue'}/>)}</div></div></article><article className="next-action"><span className="action-icon"><Icon name="target" size={21}/></span><p>Recommended next step</p><h2>Practice Graph traversal patterns</h2><span className="action-description">Your graph accuracy is 42%, and this topic is frequently tested for this target.</span><Button onClick={() => setPage('Practice')} icon="practice">Start practice</Button></article></section><section className="dashboard-grid content-grid-two"><article className="section-panel today-panel"><div className="section-head"><div><h2>Today’s preparation</h2><span>{completedPlan.length} of {todayPlan.length} activities completed</span></div><button onClick={() => setPage('Roadmap')}>View roadmap <Icon name="arrow" size={15}/></button></div><div className="plan-list">{todayPlan.map(item => <button key={item.id} className={cx('plan-item', completedPlan.includes(item.id) && 'complete')} onClick={() => togglePlan(item.id)}><span className="check-box">{completedPlan.includes(item.id) && <Icon name="check" size={14}/>}</span><span className="plan-copy"><b>{item.title}</b><small>{item.subject} · {item.duration}</small></span><em className={item.priority.toLowerCase()}>{item.priority}</em></button>)}</div></article><article className="section-panel weak-panel"><div className="section-head"><div><h2>Areas to improve</h2><span>Prioritized from recent attempts</span></div><button onClick={() => setPage('Readiness')}>View all <Icon name="arrow" size={15}/></button></div><div className="weak-list"><WeakArea name="Graphs" score={42} note="12 questions attempted"/><WeakArea name="System Design" score={48} note="1 mock interview pending"/><WeakArea name="Operating Systems" score={51} note="Revise process scheduling"/></div></article></section><section className="dashboard-grid lower-grid"><article className="section-panel performance-panel"><div className="section-head"><div><h2>Recent mock test performance</h2><span>Last 3 completed assessments</span></div><button onClick={() => setPage('Mock Tests')}>Take mock test <Icon name="arrow" size={15}/></button></div><div className="test-history"><TestResult name="Google SWE readiness test" date="28 Sep" score={81}/><TestResult name="Core CS checkpoint" date="23 Sep" score={78}/><TestResult name="DSA pattern assessment" date="17 Sep" score={72}/></div></article><article className="section-panel progress-panel"><div className="section-head"><div><h2>Preparation progress</h2><span>Across your active plan</span></div></div><div className="compact-stats"><Stat value="148" label="Questions solved"/><Stat value="8" label="Mock tests"/><Stat value="31h" label="Study hours"/><Stat value="12d" label="Current streak"/></div><div className="roadmap-meter"><span>Roadmap completion</span><b>{roadmapDone.length} / {totalRoadmap} milestones</b><ProgressBar value={Math.round(roadmapDone.length / totalRoadmap * 100)} tone="blue"/></div></article></section></> }
function WeakArea({ name, score, note }) { return <div className="weak-row"><div><strong>{name}</strong><span>{note}</span></div><b>{score}%</b><ProgressBar value={score} tone="orange"/></div> }
function TestResult({ name, date, score }) { return <div className="test-result"><div className="result-icon"><Icon name="test" size={16}/></div><div><strong>{name}</strong><span>{date}</span></div><b>{score}%</b><ProgressBar value={score} tone="green" showValue={false}/></div> }
function Stat({ value, label }) { return <div><strong>{value}</strong><span>{label}</span></div> }

function Companies({ currentCompany, setTarget, setPage }) { const [query, setQuery] = useState(''), [difficulty, setDifficulty] = useState('All'), [comparison, setComparison] = useState([]); const filtered = companies.filter(company => (company.name.toLowerCase().includes(query.toLowerCase()) || company.roles.join(' ').toLowerCase().includes(query.toLowerCase())) && (difficulty === 'All' || company.difficulty === difficulty)); const toggleCompare = id => setComparison(comparison.includes(id) ? comparison.filter(item => item !== id) : comparison.length < 3 ? [...comparison, id] : comparison); return <><PageHeader eyebrow="COMPANY EXPLORER" title="Prepare for the companies you want." description="Compare recruitment patterns, essential skills and your current readiness."><Button kind="secondary" onClick={() => setComparison([])}>Clear comparison</Button><Button onClick={() => setPage('Company guide')}>Open target guide</Button></PageHeader><section className="company-toolbar"><label className="search-input"><Icon name="filter" size={17}/><input placeholder="Search companies or roles" value={query} onChange={event => setQuery(event.target.value)}/></label><label className="select-input"><select value={difficulty} onChange={event => setDifficulty(event.target.value)}><option>All</option><option>Foundation</option><option>Intermediate</option><option>Advanced</option></select></label><span>{filtered.length} companies</span></section>{comparison.length > 0 && <section className="comparison-bar"><span><b>{comparison.length}</b> companies selected for comparison</span><div>{comparison.map(id => { const company = companies.find(item => item.id === id); return <button key={id} onClick={() => toggleCompare(id)}>{company.name} <Icon name="close" size={13}/></button> })}</div><Button onClick={() => setPage('Analytics')}>Compare readiness <Icon name="arrow" size={15}/></Button></section>}<section className="company-grid">{filtered.map(company => <article key={company.id} className={cx('company-card', company.id === currentCompany.id && 'targeted')}><div className="company-card-top"><CompanyMark company={company}/>{company.id === currentCompany.id && <span className="targeted-tag">Your target</span>}<button className={cx('compare-control', comparison.includes(company.id) && 'selected')} onClick={() => toggleCompare(company.id)}>{comparison.includes(company.id) ? <Icon name="check" size={14}/> : <Icon name="plus" size={14}/>} Compare</button></div><h2>{company.name}</h2><p>{company.roles[0]}</p><div className="company-tags"><span>{company.difficulty}</span><span>{company.rounds.length} rounds</span></div><div className="company-readiness"><div><span>Readiness</span><b>{company.readiness}%</b></div><ProgressBar value={company.readiness} tone={company.readiness > 75 ? 'green' : 'blue'} showValue={false}/></div><div className="company-skills">{company.skills.slice(0, 4).map(skill => <span key={skill}>{skill}</span>)}</div><div className="company-card-actions"><button onClick={() => { setTarget(company.id, company.roles[0]); setPage('Company guide') }}>View preparation <Icon name="arrow" size={15}/></button></div></article>)}</section>{filtered.length === 0 && <EmptyState icon="companies" title="No company found" text="Try a different search or remove the active filter."/>}</> }

function CompanyGuide({ currentCompany, role, setPage }) { const [tab, setTab] = useState('Guide'); const process = currentCompany.rounds; return <><div className="guide-hero"><div><div className="guide-title"><CompanyMark company={currentCompany} large/><div><p>COMPANY PREPARATION GUIDE</p><h1>{currentCompany.name} · {role}</h1></div></div><span>{currentCompany.description}</span></div><div className="guide-score"><span>Your readiness</span><b>{currentCompany.readiness}%</b><ProgressBar value={currentCompany.readiness} tone="blue" showValue={false}/></div></div><div className="guide-tabs">{['Guide','Topics & progress','Interview experiences'].map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>{tab === 'Guide' && <section className="guide-layout"><div><article className="guide-section"><h2>Recruitment process</h2><p>Typical process for the selected role. Confirm current campus-drive requirements when they are announced.</p><ol className="process-timeline">{process.map((step, index) => <li key={step}><span>{index + 1}</span><div><b>{step}</b><small>{index === 0 ? 'Assess core foundations and coding speed' : index === process.length - 1 ? 'Discuss fit, projects and motivation' : 'Evaluate technical depth and problem solving'}</small></div></li>)}</ol></article><article className="guide-section"><h2>Recommended preparation</h2><div className="recommendations"><div><b>1</b><span><strong>Strengthen high-frequency DSA patterns</strong><small>Arrays, trees, graphs and dynamic programming</small></span></div><div><b>2</b><span><strong>Revise core computer science</strong><small>Prioritize DBMS, OS, OOP and networking</small></span></div><div><b>3</b><span><strong>Practice explaining your work</strong><small>Prepare project walkthroughs and behavioural stories</small></span></div></div></article></div><aside className="guide-side"><section><h3>Required skills</h3><div className="skill-cloud">{currentCompany.skills.concat(['SQL','React']).map(skill => <span key={skill}>{skill}</span>)}</div></section><section><h3>Next action</h3><p>Complete a company-specific coding assessment to validate your DSA readiness.</p><Button onClick={() => setPage('Mock Tests')} icon="test">Start mock test</Button></section></aside></section>}{tab === 'Topics & progress' && <TopicProgress setPage={setPage}/>} {tab === 'Interview experiences' && <InterviewExperiences/>}</> }
function TopicProgress({ setPage }) { return <section className="topic-progress"><article><h2>Frequently tested topics</h2><p>Based on the company preparation library and tagged question bank.</p>{[['Arrays & Strings',84],['Trees & Graphs',42],['DBMS & SQL',74],['Operating Systems',51],['System Design',48]].map(([name,value]) => <ProgressBar key={name} label={name} value={value} tone={value < 60 ? 'orange' : 'blue'}/>)}</article><article><h2>Preparation insight</h2><p>Graphs, Operating Systems and System Design offer the strongest readiness gains right now.</p><Button onClick={() => setPage('Practice')} icon="practice">Practice weak topics</Button></article></section> }
function InterviewExperiences() { return <section className="experiences"><article><span className="experience-label">TECHNICAL INTERVIEW · 2026</span><h2>“The interviewer focused on approach before code.”</h2><p>Discussed tree traversal, API design choices and the candidate’s final-year project. Clear trade-offs and test cases were valued.</p><div><b>45 min</b><span>Data structures · project discussion</span></div></article><article><span className="experience-label">ONLINE ASSESSMENT · 2026</span><h2>“Two medium coding problems in 75 minutes.”</h2><p>Questions covered arrays, strings and a SQL query. Time management made the difference for the final problem.</p><div><b>75 min</b><span>2 coding problems · 10 MCQs</span></div></article></section> }

function Practice({ currentCompany, bookmarks, setBookmarks, reviewed, setReviewed, showToast }) { const [subject, setSubject] = useState('All subjects'), [difficulty, setDifficulty] = useState('All difficulties'), [query, setQuery] = useState(''), [selectedId, setSelectedId] = useState(1), [attempting, setAttempting] = useState(false), [answer, setAnswer] = useState(''); const filtered = questions.filter(question => (subject === 'All subjects' || question.subject === subject) && (difficulty === 'All difficulties' || question.difficulty === difficulty) && (question.title.toLowerCase().includes(query.toLowerCase()) || question.topic.toLowerCase().includes(query.toLowerCase()))); const question = filtered.find(item => item.id === selectedId) || filtered[0]; useEffect(() => { if (question) setSelectedId(question.id) }, [subject,difficulty,query]); const toggle = (array, setArray, id, label) => { const next = array.includes(id) ? array.filter(item => item !== id) : [...array,id]; setArray(next); showToast(array.includes(id) ? `${label} removed` : `${label} saved`) }; return <><PageHeader eyebrow="QUESTION PRACTICE" title="Practice with purpose." description={`${currentCompany.name} · Company-tagged questions and focused progress.`}><Button kind="secondary" onClick={() => setSelectedId(filtered[(filtered.findIndex(item => item.id === question?.id) + 1) % filtered.length]?.id)}>Next question <Icon name="arrow" size={15}/></Button></PageHeader><section className="practice-layout"><aside className="practice-filter"><h3>Filter questions</h3><label>Search<input value={query} onChange={event => setQuery(event.target.value)} placeholder="Topic or question"/></label><label>Company<select><option>{currentCompany.name}</option><option>All companies</option></select></label><label>Subject<select value={subject} onChange={event => setSubject(event.target.value)}><option>All subjects</option>{['DSA','Core CS','DBMS','System Design'].map(item => <option key={item}>{item}</option>)}</select></label><label>Difficulty<select value={difficulty} onChange={event => setDifficulty(event.target.value)}><option>All difficulties</option>{['Easy','Medium','Hard'].map(item => <option key={item}>{item}</option>)}</select></label><div className="filter-count"><b>{filtered.length}</b> matching questions</div></aside>{question ? <article className="question-surface"><div className="question-head"><div><span className={cx('difficulty', question.difficulty.toLowerCase())}>{question.difficulty}</span><span className="topic-tag">{question.topic}</span></div><div className="question-actions"><button className={bookmarks.includes(question.id) ? 'active' : ''} onClick={() => toggle(bookmarks,setBookmarks,question.id,'Bookmark')}><Icon name="bookmark" size={17}/></button><button className={reviewed.includes(question.id) ? 'active' : ''} onClick={() => toggle(reviewed,setReviewed,question.id,'Question for review')}>Mark for review</button></div></div><h1>{question.title}</h1><div className="question-meta"><span><CompanyMark company={companies.find(item => item.name === question.company) || currentCompany}/>{question.company}</span><span><Icon name="timer" size={15}/>{question.time}</span><span>{question.subject}</span></div><p className="question-statement">{question.statement}</p><section className="example-box"><span>Example</span><pre>{question.examples}</pre></section>{attempting && <section className="answer-workspace"><div><b>Your approach</b><span>Write pseudocode, notes or your solution idea.</span></div><textarea value={answer} onChange={event => setAnswer(event.target.value)} placeholder="Explain your approach before you code…"/><div><Button kind="secondary" onClick={() => setAttempting(false)}>Cancel</Button><Button onClick={() => showToast(answer.trim() ? 'Approach saved to your practice history' : 'Add your approach before saving', answer.trim() ? 'success' : 'warning')}>Save approach</Button></div></section>}{!attempting && <div className="question-footer"><Button onClick={() => setAttempting(true)} icon="practice">Attempt question</Button><button onClick={() => { setSelectedId(filtered[(filtered.findIndex(item => item.id === question.id) + 1) % filtered.length]?.id); setAttempting(false); setAnswer('') }}>Skip for now <Icon name="arrow" size={15}/></button></div>}</article> : <EmptyState icon="practice" title="No questions match these filters" text="Adjust the subject, difficulty or search term to continue."/>}<aside className="question-sidebar"><h3>Question progress</h3><div className="practice-count"><b>8</b><span>of 15 completed in this topic</span></div><ProgressBar value={53} tone="blue"/><hr/><h3>Up next</h3>{filtered.slice(0,3).map(item => <button key={item.id} className={cx('mini-question', item.id === question?.id && 'active')} onClick={() => { setSelectedId(item.id); setAttempting(false) }}><span>{item.difficulty[0]}</span><div><b>{item.title}</b><small>{item.topic} · {item.time}</small></div></button>)}</aside></section></> }

function MockTests({ showToast }) { const [activeIndex, setActiveIndex] = useState(0), [answers, setAnswers] = useState({}), [marked, setMarked] = useState([]), [seconds, setSeconds] = useState(45 * 60), [submitted, setSubmitted] = useState(false); useEffect(() => { if (submitted || seconds <= 0) return; const timer = window.setInterval(() => setSeconds(value => value - 1), 1000); return () => window.clearInterval(timer) }, [submitted,seconds]); useEffect(() => { if (seconds === 0 && !submitted) setSubmitted(true) }, [seconds,submitted]); const question = mockQuestions[activeIndex], correct = mockQuestions.filter(item => answers[item.id] === item.answer).length, formatTime = value => `${String(Math.floor(value / 60)).padStart(2,'0')}:${String(value % 60).padStart(2,'0')}`; if (submitted) return <MockResult correct={correct} restart={() => { setAnswers({}); setMarked([]); setActiveIndex(0); setSeconds(45*60); setSubmitted(false) }}/>; return <><PageHeader eyebrow="MOCK TEST" title="Google · Software Engineer readiness test" description="20 questions · 45 minutes · Progress is saved during this session."><div className="test-timer"><Icon name="timer" size={17}/><b>{formatTime(seconds)}</b><span>remaining</span></div><Button kind="danger" onClick={() => { setSubmitted(true); showToast('Test submitted') }}>Submit test</Button></PageHeader><section className="exam-layout"><article className="exam-question"><div className="exam-head"><span>Question {activeIndex + 1} of {mockQuestions.length}</span><span>{question.subject}</span></div><h2>{question.question}</h2><div className="answer-options">{question.options.map((option,index) => <button key={option} className={answers[question.id] === index ? 'selected' : ''} onClick={() => setAnswers({ ...answers, [question.id]: index })}><i>{String.fromCharCode(65 + index)}</i>{option}</button>)}</div><div className="exam-actions"><Button kind="secondary" disabled={activeIndex === 0} onClick={() => setActiveIndex(activeIndex - 1)}>Previous</Button><div><button className={marked.includes(question.id) ? 'mark-active' : ''} onClick={() => setMarked(marked.includes(question.id) ? marked.filter(id => id !== question.id) : [...marked,question.id])}>{marked.includes(question.id) ? 'Marked for review' : 'Mark for review'}</button><Button onClick={() => setActiveIndex(activeIndex < mockQuestions.length - 1 ? activeIndex + 1 : activeIndex)}>Next question <Icon name="arrow" size={15}/></Button></div></div></article><aside className="test-navigator"><h3>Question navigator</h3><div className="navigator-grid">{mockQuestions.map((item,index) => <button key={item.id} className={cx(index === activeIndex && 'current', answers[item.id] !== undefined && 'answered', marked.includes(item.id) && 'marked')} onClick={() => setActiveIndex(index)}>{index + 1}</button>)}</div><div className="navigator-key"><span><i className="answered"/>Answered</span><span><i className="marked"/>Marked</span><span><i className="current"/>Current</span></div><hr/><div className="exam-status"><span>Answered <b>{Object.keys(answers).length}/{mockQuestions.length}</b></span><span>Marked <b>{marked.length}</b></span></div><Button kind="danger" onClick={() => setSubmitted(true)}>Submit test</Button></aside></section></> }
function MockResult({ correct, restart }) { const score = Math.round(correct / mockQuestions.length * 100); return <><PageHeader eyebrow="MOCK TEST RESULT" title="Your result is ready." description="Review the outcome, then use the feedback to plan your next session."/><section className="result-layout"><article className="result-score"><span>Overall score</span><b>{score}%</b><p>{correct} of {mockQuestions.length} answers correct</p><div className={cx('result-status', score >= 70 ? 'good' : 'attention')}>{score >= 70 ? 'Good progress - keep practicing' : 'Focus on the weak topics below'}</div><Button onClick={restart}>Retake this test</Button></article><article className="result-breakdown"><h2>Topic breakdown</h2>{[['DSA',78],['DBMS',82],['Operating Systems',51],['Aptitude',88],['OOP & SQL',66]].map(([name,value]) => <ProgressBar key={name} label={name} value={value} tone={value < 60 ? 'orange' : 'green'}/>)}</article><article className="result-next"><h2>Recommended next steps</h2><ol><li>Revise operating-system scheduling concepts.</li><li>Attempt a focused DSA pattern set.</li><li>Schedule your next mock test after revision.</li></ol></article></section></> }

function Roadmap({ roadmapDone, setRoadmapDone, showToast, setPage }) {
  const steps = [
    { number: 'Step 1', title: 'Learn', action: 'Start Learning', items: [{ id: 'learn-js', title: 'JavaScript', detail: 'Language fundamentals and ES6' }, { id: 'learn-react', title: 'React', detail: 'Components, state and hooks' }, { id: 'learn-node', title: 'Node.js', detail: 'APIs and backend basics' }, { id: 'learn-sql', title: 'SQL', detail: 'Queries, joins and schema design' }] },
    { number: 'Step 2', title: 'Practice', action: 'Continue', items: [{ id: 'practice-coding', title: 'Coding Questions', detail: 'Arrays, strings and problem patterns' }, { id: 'practice-sql', title: 'SQL Questions', detail: 'Company-style database questions' }, { id: 'practice-dsa', title: 'DSA Problems', detail: 'High-frequency interview problems' }, { id: 'practice-aptitude', title: 'Aptitude', detail: 'Quantitative and logical reasoning' }] },
    { number: 'Step 3', title: 'Interview Preparation', action: 'Continue', items: [{ id: 'interview-tech', title: 'Technical Questions', detail: 'Explain concepts with confidence' }, { id: 'interview-hr', title: 'HR Questions', detail: 'Tell your story clearly' }, { id: 'interview-company', title: 'Company Questions', detail: 'Know your target company' }] },
  ]
  const complete = id => roadmapDone.includes(id)
  const toggle = item => { const done = complete(item.id); setRoadmapDone(done ? roadmapDone.filter(id => id !== item.id) : [...roadmapDone, item.id]); showToast(done ? `${item.title} moved back to your roadmap` : `${item.title} marked complete`) }
  const total = steps.flatMap(step => step.items).length
  const doneCount = steps.flatMap(step => step.items).filter(item => complete(item.id)).length
  return <><PageHeader eyebrow="YOUR PREPARATION ROADMAP" title="Your Preparation Roadmap" description="Move through the journey one simple step at a time."><div className="roadmap-summary"><b>{doneCount}/{total}</b><span>activities complete</span><ProgressBar value={Math.round(doneCount / total * 100)} tone="blue" showValue={false}/></div></PageHeader><section className="journey-roadmap">{steps.map((step, index) => <article className="journey-step" key={step.title}><header><span>{index + 1}</span><div><small>{step.number}</small><h2>{step.title}</h2></div><b>{step.items.filter(item => complete(item.id)).length}/{step.items.length} complete</b><Button kind="secondary" onClick={() => setPage(index === 1 ? 'Practice' : index === 2 ? 'AI Interview' : 'Requirements')}>{step.action} <Icon name="arrow" size={15}/></Button></header><div>{step.items.map(item => <button key={item.id} className={cx('journey-item', complete(item.id) && 'done')} onClick={() => toggle(item)}><span>{complete(item.id) ? <Icon name="check" size={14}/> : ''}</span><div><strong>{item.title}</strong><small>{item.detail}</small></div><em>{complete(item.id) ? 'Completed' : 'Not started'}</em></button>)}</div></article>)}</section></>
}

function Progress({ completedPlan, roadmapDone }) { const week = [{day:'Mon',value:55},{day:'Tue',value:76},{day:'Wed',value:42},{day:'Thu',value:92},{day:'Fri',value:64},{day:'Sat',value:83},{day:'Sun',value:36}]; return <><PageHeader eyebrow="PREPARATION PROGRESS" title="See the work behind your readiness." description="Track effort and completion across every preparation activity."/><section className="progress-summary-grid"><MetricCard value="148" label="Questions solved" detail="+12 this week" tone="blue"/><MetricCard value="78%" label="Question accuracy" detail="+4% this week" tone="green"/><MetricCard value="8" label="Mock tests" detail="2 scheduled next" tone="orange"/><MetricCard value="12 days" label="Current streak" detail="Best: 18 days" tone="blue"/></section><section className="progress-page-grid"><article className="section-panel study-chart"><div className="section-head"><div><h2>Study activity</h2><span>Focused study time in the last 7 days</span></div><b>8h 40m</b></div><div className="activity-chart">{week.map(item => <div key={item.day}><span style={{height:pct(item.value)}}/><small>{item.day}</small></div>)}</div><div className="chart-legend"><span><i/>Focused preparation</span><b>Weekly goal: 10h</b></div></article><article className="section-panel completion-overview"><h2>Current completion</h2><div><div><b>{completedPlan.length}</b><span>Today’s activities</span></div><div><b>{roadmapDone.length}</b><span>Roadmap milestones</span></div></div><p>Finish one more activity today to stay above your weekly target.</p></article></section><section className="section-panel activity-log"><div className="section-head"><div><h2>Recent activity</h2><span>Latest milestones and assessments</span></div></div><div className="activity-table"><LogRow title="Completed Arrays & Strings revision" type="Roadmap" time="Today, 10:30 AM" state="Completed"/><LogRow title="Attempted Google SWE readiness test" type="Mock test" time="28 Sep, 7:45 PM" state="Score: 81%"/><LogRow title="Solved Longest Consecutive Sequence" type="Practice" time="28 Sep, 6:30 PM" state="Solved"/></div></section></> }
function MetricCard({ value,label,detail,tone }) { return <article className={cx('metric-card',tone)}><span>{label}</span><b>{value}</b><small>{detail}</small></article> }
function LogRow({ title,type,time,state }) { return <div className="log-row"><div className="log-dot"><Icon name="check" size={14}/></div><div><b>{title}</b><span>{type} · {time}</span></div><em>{state}</em></div> }

function Readiness({ setPage }) { const overall = Math.round(readinessSkills.reduce((sum,skill) => sum + skill.score, 0) / readinessSkills.length); return <><PageHeader eyebrow="READINESS ANALYSIS" title="Know exactly where you stand." description="Your score combines practice accuracy, mock tests, roadmap completion and interview preparation."><Button onClick={() => setPage('Roadmap')}>Follow recommended plan <Icon name="arrow" size={15}/></Button></PageHeader><section className="readiness-page-grid"><article className="readiness-main"><div className="readiness-number"><span>Overall readiness</span><b>{overall}<small>/100</small></b><p>On track for your target role</p></div><div className="readiness-detail">{readinessSkills.map(skill => <ProgressBar key={skill.name} label={skill.name} value={skill.score} tone={skill.status === 'strong' ? 'green' : skill.status === 'needs work' ? 'orange' : 'blue'}/>)}</div></article><aside className="readiness-note"><h2>How to improve this score</h2><p>Completing company-tagged practice and interview sessions has the highest impact this week.</p><Button kind="secondary" onClick={() => setPage('Practice')} icon="practice">Practice weak areas</Button></aside></section><section className="strengths-grid"><article><h2>Strong areas</h2><SkillState name="Aptitude" score="81" note="Consistent accuracy across the last 3 sessions" type="strong"/><SkillState name="SQL" score="84" note="Fast, accurate query-writing performance" type="strong"/></article><article><h2>Needs improvement</h2><SkillState name="Graphs" score="42" note="Revisit traversals before advanced problems" type="attention"/><SkillState name="Interview" score="62" note="Practice technical explanations out loud" type="attention"/></article><article className="action-list"><h2>Recommended next actions</h2><ol><li>Practice 5 graph-traversal questions.</li><li>Revise process scheduling in Operating Systems.</li><li>Complete one technical mock interview.</li></ol></article></section></> }
function SkillState({ name,score,note,type }) { return <div className="skill-state"><b className={type}>{score}</b><div><strong>{name}</strong><span>{note}</span></div></div> }

function ResumeAnalyzer({ showToast }) { const [file,setFile] = useState(null), [analyzed,setAnalyzed] = useState(false); return <><PageHeader eyebrow="AI RESUME ANALYZER" title="Make your resume role-ready." description="Compare your skills with the selected target role and find high-value improvements."/>{!analyzed ? <section className="resume-layout"><article className="upload-card"><span className="upload-icon"><Icon name="upload" size={25}/></span><h2>Upload your resume</h2><p>Use a PDF or DOCX. HireVerse will extract skills and compare them with your target role.</p><input id="resume-upload" type="file" accept=".pdf,.doc,.docx" onChange={event => { setFile(event.target.files?.[0] || null); setAnalyzed(false) }}/><label htmlFor="resume-upload" className="file-label">Choose resume file</label><small>Maximum file size: 10 MB</small>{file && <div className="uploaded-file"><Icon name="file" size={19}/><span><b>{file.name}</b><small>Uploaded successfully</small></span><button onClick={() => setFile(null)}><Icon name="close" size={16}/></button></div>}<Button disabled={!file} onClick={() => { setAnalyzed(true); showToast('Resume analysis completed') }}>Analyze resume <Icon name="arrow" size={15}/></Button></article><aside className="resume-tips"><h2>What we analyze</h2><ul><li>Skills relevant to your target role</li><li>Keywords and ATS readability</li><li>Project impact and achievement statements</li><li>Missing or underrepresented skills</li></ul><div><Icon name="assistant" size={18}/><span>Your resume is analyzed only for personalized preparation insights.</span></div></aside></section> : <ResumeResults file={file} restart={() => { setFile(null); setAnalyzed(false) }}/>}</> }
function ResumeResults({ file,restart }) { return <section className="resume-results"><article className="resume-score"><span>Resume analysis · {file?.name}</span><h2>ATS score <b>78</b><small>/100</small></h2><p>Your resume has a clear technical foundation. Add evidence of scale and close the remaining skill gaps for your target role.</p><Button kind="secondary" onClick={restart}>Analyze another resume</Button></article><article><h2>Matched skills</h2><p>Strong signals found in your resume.</p><div className="skill-cloud matched">{['React','JavaScript','SQL','MongoDB','REST APIs','Git'].map(skill => <span key={skill}>{skill}</span>)}</div><h2>Missing or underrepresented</h2><div className="skill-cloud missing">{['Docker','System Design','Advanced DSA'].map(skill => <span key={skill}>{skill}</span>)}</div></article><article className="resume-improvements"><h2>Recommended improvements</h2><ol><li>Add measurable outcomes to your two strongest projects.</li><li>Include a concise system-design project or deployment detail.</li><li>Surface DSA and problem-solving work in your skills section.</li></ol></article></section> }

function Assistant({ currentCompany,role }) { const initial = [{ from:'assistant', text:`I can help you prepare for ${currentCompany.name} ${role} interviews. Ask about its recruitment process, topics or preparation strategy.`, sources:[assistantSources[0]] }]; const [messages,setMessages] = useState(initial), [input,setInput] = useState(''); const send = value => { const question = value.trim(); if (!question) return; const answer = question.toLowerCase().includes('dbms') ? `For ${currentCompany.name}, prioritize DBMS transactions, normalization, indexing, joins and SQL query practice. Start with transactions and isolation levels because your current DBMS practice shows room to build confidence.` : `For ${currentCompany.name} ${role}, focus first on DSA patterns, core CS fundamentals, and clearly explaining your project decisions. I recommend following the roadmap’s next high-priority activity.`; setMessages([...messages,{from:'student',text:question},{from:'assistant',text:answer,sources:[assistantSources[1],assistantSources[2]]}]); setInput('') }; return <><PageHeader eyebrow="COMPANY INFORMATION ASSISTANT" title="HireVerse Assistant" description="Ask company-specific preparation questions and receive answers grounded in the HireVerse preparation library."/><section className="assistant-layout"><aside className="conversation-list"><div><h3>Conversations</h3><button onClick={() => setMessages(initial)}><Icon name="plus" size={15}/> New conversation</button></div><button className="conversation active"><b>{currentCompany.name} preparation plan</b><span>Updated just now</span></button><button className="conversation"><b>DBMS interview revision</b><span>Yesterday</span></button><button className="conversation"><b>Resume skill gaps</b><span>26 Sep</span></button></aside><article className="chat-surface"><div className="chat-head"><div><CompanyMark company={currentCompany}/><div><strong>{currentCompany.name} preparation assistant</strong><span>{role} · Context enabled</span></div></div><span><i/>Online</span></div><div className="messages">{messages.map((message,index) => <div key={index} className={cx('message',message.from)}>{message.from === 'assistant' && <span className="assistant-avatar">H</span>}<div><p>{message.text}</p>{message.sources && <div className="message-sources">{message.sources.map(source => <span key={source.title}><Icon name="file" size={13}/>{source.title}</span>)}</div>}</div></div>)}</div><div className="suggested-prompts">{['What is the recruitment process?','Which DSA topics should I prepare?','What DBMS topics are important?'].map(prompt => <button key={prompt} onClick={() => send(prompt)}>{prompt}</button>)}</div><form className="chat-input" onSubmit={event => { event.preventDefault(); send(input) }}><input value={input} onChange={event => setInput(event.target.value)} placeholder={`Ask about ${currentCompany.name} preparation…`}/><button type="submit" aria-label="Send message"><Icon name="send" size={18}/></button></form></article><aside className="assistant-context"><h3>Company context</h3><div><span>Target</span><b>{currentCompany.name}</b></div><div><span>Role</span><b>{role}</b></div><div><span>Readiness</span><b>{currentCompany.readiness}%</b></div><hr/><h3>Available sources</h3>{assistantSources.map(source => <article key={source.title}><Icon name="file" size={16}/><span><b>{source.title}</b><small>{source.note}</small></span></article>)}</aside></section></> }

function Interview({ currentCompany,role,showToast }) { const [type,setType] = useState('Technical'), [stage,setStage] = useState('setup'), [answer,setAnswer] = useState(''), [seconds,setSeconds] = useState(8*60); useEffect(() => { if (stage !== 'active' || seconds === 0) return; const timer = window.setInterval(() => setSeconds(value => value - 1),1000); return () => window.clearInterval(timer) },[stage,seconds]); const format = value => `${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`; if (stage === 'feedback') return <InterviewFeedback restart={() => { setStage('setup'); setAnswer(''); setSeconds(8*60) }}/>; if (stage === 'active') return <><PageHeader eyebrow="AI MOCK INTERVIEW" title="Interview in progress"><div className="interview-timer"><Icon name="timer" size={17}/>{format(seconds)}</div></PageHeader><section className="interview-room"><aside><div className="interviewer-avatar">H</div><b>HireVerse Interviewer</b><span>{type} interview · {currentCompany.name}</span><hr/><p>Take a moment to structure your answer. Explain your thinking as you would in a real interview.</p><div className="interview-progress"><span>Question 1 of 5</span><ProgressBar value={20} tone="blue" showValue={false}/></div></aside><article><span className="interview-question-label">QUESTION 01</span><h2>{type === 'Technical' ? 'Explain the difference between INNER JOIN and LEFT JOIN. When would you use each?' : type === 'HR' ? 'Tell me about a time you handled a challenging project situation.' : 'Describe a time you received difficult feedback and what you did with it.'}</h2><p>Record your answer in a clear, structured way. Aim for concise technical explanation or STAR-based storytelling.</p><textarea value={answer} onChange={event => setAnswer(event.target.value)} placeholder="Type your answer here…"/><div><span>{answer.split(/\s+/).filter(Boolean).length} words</span><Button onClick={() => { if (!answer.trim()) return showToast('Add an answer before submitting','warning'); setStage('feedback'); showToast('Answer evaluated') }}>Submit answer <Icon name="arrow" size={15}/></Button></div></article></section></>; return <><PageHeader eyebrow="AI MOCK INTERVIEW" title="Practice your interview, before it counts." description="Receive structured feedback on your answers for your selected company and role."/><section className="interview-setup"><article><h2>Set up your interview</h2><div className="setup-target"><CompanyMark company={currentCompany} large/><div><b>{currentCompany.name}</b><span>{role}</span></div></div><label className="field-label">Interview type<select value={type} onChange={event => setType(event.target.value)}><option>Technical</option><option>HR</option><option>Behavioral</option></select></label><label className="field-label">Difficulty<select><option>Role matched</option><option>Foundation</option><option>Advanced</option></select></label><Button onClick={() => setStage('active')} icon="interview">Start interview</Button></article><aside><h2>What you’ll get</h2><ul><li>Company and role-aligned questions</li><li>Feedback on technical knowledge and clarity</li><li>Specific suggestions for your next practice</li></ul><div className="setup-note"><Icon name="timer" size={18}/><span>Estimated time: 15–20 minutes</span></div></aside></section></> }
function InterviewFeedback({ restart }) { return <><PageHeader eyebrow="AI MOCK INTERVIEW" title="Your interview feedback." description="Use the findings below to make the next answer clearer and more confident."/><section className="feedback-layout"><article className="feedback-score"><span>Overall interview score</span><b>74<small>/100</small></b><p>A solid technical foundation. Strengthen answer structure and include a clearer practical example.</p><Button onClick={restart}>Try another interview</Button></article><article><h2>Performance breakdown</h2><ProgressBar label="Technical knowledge" value={78} tone="green"/><ProgressBar label="Answer quality" value={71} tone="blue"/><ProgressBar label="Communication" value={69} tone="orange"/><ProgressBar label="Confidence" value={76} tone="green"/></article><article className="feedback-note"><h2>Suggested improvement</h2><p>Lead with a one-sentence distinction, then give a compact use case for each join type. This makes the answer easier to follow.</p><span>Next recommendation</span><b>Practice 3 SQL interview questions</b></article></section></> }

function Analytics({ currentCompany }) { const [view,setView] = useState('Accuracy'); const chart = view === 'Accuracy' ? [58,62,65,61,72,76,78] : [55,56,66,71,74,80,82]; return <><PageHeader eyebrow="PREPARATION ANALYTICS" title="Insights that improve your next session." description="Use performance trends to decide what to study, not just what to track."/><section className="analytics-grid"><article className="section-panel trend-panel"><div className="section-head"><div><h2>Preparation trend</h2><span>Last 7 practice sessions</span></div><div className="segmented"><button className={view === 'Accuracy' ? 'active' : ''} onClick={() => setView('Accuracy')}>Accuracy</button><button className={view === 'Readiness' ? 'active' : ''} onClick={() => setView('Readiness')}>Readiness</button></div></div><div className="line-chart"><svg viewBox="0 0 600 180" preserveAspectRatio="none"><polyline points={chart.map((value,index) => `${index*100},${175-value*1.45}`).join(' ')} fill="none" stroke="#276ad9" strokeWidth="4" strokeLinejoin="round" strokeLinecap="round"/><polyline points={`0,180 ${chart.map((value,index) => `${index*100},${175-value*1.45}`).join(' ')} 600,180`} fill="#276ad91a" stroke="none"/></svg><div>{['Sep 18','Sep 20','Sep 22','Sep 24','Sep 26','Sep 28','Today'].map(day => <span key={day}>{day}</span>)}</div></div></article><article className="section-panel accuracy-card"><h2>Question accuracy</h2><b>78%</b><span>+6% from previous week</span><ProgressBar value={78} tone="green" showValue={false}/><p>You are strongest in Aptitude and SQL. Keep the consistency while investing more time in graph patterns.</p></article></section><section className="analytics-grid lower-analytics"><article className="section-panel topic-analysis"><div className="section-head"><div><h2>Topic-wise performance</h2><span>Accuracy from recent attempts</span></div></div>{[['Aptitude',88],['SQL',84],['DBMS',74],['Arrays',71],['Graphs',42],['Operating Systems',51]].map(([name,value]) => <ProgressBar key={name} label={name} value={value} tone={value < 60 ? 'orange' : value > 80 ? 'green' : 'blue'}/>)}</article><article className="section-panel comparison-analysis"><h2>Company readiness comparison</h2><p>Compare your current preparation strength across saved company targets.</p>{companies.slice(0,4).map(company => <div className={company.id === currentCompany.id ? 'selected-company' : ''} key={company.id}><CompanyMark company={company}/><span>{company.name}</span><b>{company.readiness}%</b><ProgressBar value={company.readiness} tone={company.id === currentCompany.id ? 'blue' : 'green'} showValue={false}/></div>)}</article></section></> }

function Admin({ adminQuestions,setAdminQuestions,showToast }) { const [newQuestion,setNewQuestion] = useState(''); const add = () => { if (!newQuestion.trim()) return; setAdminQuestions([{id:Date.now(),title:newQuestion,subject:'DSA',topic:'Arrays',difficulty:'Medium',company:'Google',time:'20 min'},...adminQuestions]); setNewQuestion(''); showToast('Question added to bank') }; return <><PageHeader eyebrow="ADMINISTRATION" title="Manage preparation content." description="Use this area to maintain question-bank content for HireVerse students."/><section className="admin-layout"><article className="section-panel"><h2>Add question</h2><p>Create a new item in the shared question bank.</p><input value={newQuestion} onChange={event => setNewQuestion(event.target.value)} placeholder="Question title"/><Button onClick={add} icon="plus">Add question</Button></article><article className="section-panel admin-table"><div className="section-head"><div><h2>Question bank</h2><span>{adminQuestions.length} questions available</span></div></div>{adminQuestions.slice(0,6).map(question => <div key={question.id}><span>{question.subject}</span><b>{question.title}</b><button onClick={() => { setAdminQuestions(adminQuestions.filter(item => item.id !== question.id)); showToast('Question removed','warning') }}>Remove</button></div>)}</article></section></> }
function PracticeTests({ showToast }) { const [selectedTest, setSelectedTest] = useState(null); const tests = [{title:'Aptitude Test',icon:'A',tone:'orange',note:'Quantitative and logical reasoning'},{title:'DSA Test',icon:'</>',tone:'blue',note:'Problem-solving patterns'},{title:'SQL Test',icon:'SQL',tone:'green',note:'Queries and database basics'},{title:'DBMS Test',icon:'DB',tone:'blue',note:'Core database concepts'},{title:'Company Test',icon:'>',tone:'purple',note:'Accenture-style assessment'}]; if (selectedTest) return <MockTests showToast={showToast}/>; return <><PageHeader eyebrow="PRACTICE TESTS" title="Practice Tests" description="Build speed and confidence with short, focused assessments."/><section className="test-cards">{tests.map(test => <article className={cx('test-card',test.tone)} key={test.title}><span>{test.icon}</span><h2>{test.title}</h2><p>{test.note}</p><small>10 Questions <i>•</i> 15 Minutes</small><Button onClick={() => { setSelectedTest(test.title); showToast(`${test.title} started`) }}>Start Test <Icon name="arrow" size={15}/></Button></article>)}</section></> }
function JourneyInterview({ currentCompany, role, showToast }) { const [type,setType] = useState('Technical'), [difficulty,setDifficulty] = useState('Medium'), [stage,setStage] = useState('setup'), [answer,setAnswer] = useState(''); if (stage === 'result') return <><PageHeader eyebrow="MOCK INTERVIEW" title="Your Result" description={`${type} interview · ${difficulty} difficulty · ${currentCompany.name}`}/><section className="simple-interview-result"><article><span>Overall Score</span><b>76<small>/100</small></b><p>Good technical foundation. Your next gain comes from making the structure of each answer more direct.</p><Button onClick={() => { setStage('setup'); setAnswer('') }}>Start another interview</Button></article><div><ProgressBar label="Technical Skills" value={78} tone="green"/><ProgressBar label="Communication" value={70} tone="blue"/><ProgressBar label="Problem Solving" value={80} tone="green"/></div><aside><h2>What to improve</h2><ol><li>Start with a direct one-sentence answer.</li><li>Use one practical example to support your explanation.</li><li>End by summarizing the key trade-off.</li></ol></aside></section></>; if (stage === 'active') return <><PageHeader eyebrow="MOCK INTERVIEW" title="Interview in progress" description={`${type} · ${difficulty} · ${currentCompany.name}`}/><section className="simple-interview-active"><span>QUESTION 1</span><h2>{type === 'HR' ? 'Tell me about a project challenge you solved with your team.' : type === 'Mixed' ? 'Explain an API you built, then describe a challenge you overcame while building it.' : 'What is the difference between INNER JOIN and LEFT JOIN, and when would you use each?'}</h2><p>Take a moment to structure your response. Aim for a clear explanation and one example.</p><textarea value={answer} onChange={event => setAnswer(event.target.value)} placeholder="Type your answer here…"/><div><small>{answer.trim() ? `${answer.trim().split(/\s+/).length} words` : 'Write your answer when ready'}</small><Button onClick={() => { if (!answer.trim()) return showToast('Add an answer before submitting','warning'); setStage('result'); showToast('Interview answer evaluated') }}>Submit answer</Button></div></section></>; return <><PageHeader eyebrow="MOCK INTERVIEW" title="Mock Interview" description="Practice a role-relevant question, then use simple feedback to improve your next answer."/><section className="simple-interview-setup"><article><h2>Choose your interview</h2><label className="field-label">Interview Type<select value={type} onChange={event => setType(event.target.value)}><option>Technical</option><option>HR</option><option>Mixed</option></select></label><label className="field-label">Difficulty<select value={difficulty} onChange={event => setDifficulty(event.target.value)}><option>Easy</option><option>Medium</option><option>Hard</option></select></label><Button onClick={() => setStage('active')} icon="interview">Start Interview</Button></article><aside><CompanyMark company={currentCompany} large/><h2>{role} at {currentCompany.name}</h2><p>HireVerse will ask one focused question at a time and give feedback on your response.</p><ul><li>Company-aligned question</li><li>Simple score breakdown</li><li>Clear improvement suggestions</li></ul></aside></section></> }
function SimpleResume({ showToast }) { const [file,setFile] = useState(null), [uploaded,setUploaded] = useState(false); if (uploaded) return <><PageHeader eyebrow="RESUME ANALYZER" title="Resume Analyzer" description="A simple check of your resume against your placement preparation goal."/><section className="simple-resume-result"><article><span>Resume Score</span><b>82<small>/100</small></b><p>Your resume presents a strong foundation. A few targeted details can make your project work more convincing.</p><Button kind="secondary" onClick={() => { setFile(null); setUploaded(false) }}>Upload another resume</Button></article><div><ProgressBar label="Skills Match" value={84} tone="green"/><ProgressBar label="Projects" value={79} tone="blue"/><ProgressBar label="Experience" value={70} tone="orange"/><ProgressBar label="ATS Score" value={82} tone="green"/></div><aside><h2>Suggestions</h2><ol><li>Add measurable outcomes to your strongest project.</li><li>Make React, Node.js and SQL easier to find in your skills section.</li><li>Include GitHub links for your best two projects.</li></ol></aside></section></>; return <><PageHeader eyebrow="RESUME ANALYZER" title="Resume Analyzer" description="Upload your resume to see the skills and sections that need attention."/><section className="simple-resume-upload"><span className="upload-icon"><Icon name="upload" size={26}/></span><h2>Upload your Resume</h2><p>PDF / DOCX</p><input id="journey-resume" type="file" accept=".pdf,.doc,.docx" onChange={event => setFile(event.target.files?.[0] || null)}/><label className="file-label" htmlFor="journey-resume">Upload Resume</label>{file && <div className="uploaded-file"><Icon name="file" size={18}/><span><b>{file.name}</b><small>Ready to analyze</small></span><button onClick={() => setFile(null)}><Icon name="close" size={15}/></button></div>}<Button disabled={!file} onClick={() => { setUploaded(true); showToast('Resume uploaded and analyzed') }}>Analyze Resume <Icon name="arrow" size={15}/></Button></section></> }
function SimpleProgress({ setPage }) { return <><PageHeader eyebrow="PREPARATION PROGRESS" title="Your Progress" description="A simple view of how ready you are for your placement goal."/><section className="simple-progress-hero"><div><span>Overall readiness</span><b>68% <small>Ready</small></b><ProgressBar value={68} tone="blue" showValue={false}/></div><p>Your learning, practice and interview preparation are moving in the right direction.</p></section><section className="progress-summary-grid simple-progress-cards"><MetricCard value="75%" label="Technical Skills" detail="Strong learning momentum" tone="blue"/><MetricCard value="50%" label="DSA" detail="Keep practicing patterns" tone="orange"/><MetricCard value="80%" label="Aptitude" detail="Your strongest area" tone="green"/><MetricCard value="60%" label="Interview" detail="Build answer confidence" tone="blue"/><MetricCard value="90%" label="Resume" detail="Resume is almost ready" tone="green"/></section><section className="continue-learning"><div><span>CONTINUE LEARNING</span><h2>You are currently learning <b>Binary Search.</b></h2><p>Pick up from the last pattern you were practicing and complete the next two questions.</p></div><Button onClick={() => setPage('Practice')} icon="practice">Continue</Button></section></> }
function EmptyState({ icon,title,text }) { return <section className="empty-state"><Icon name={icon} size={28}/><h2>{title}</h2><p>{text}</p></section> }

createRoot(document.getElementById('root')).render(<App />)
